import rosterkit.attendance
import rosterkit.models


def absence_notice(*, student, marks):
    marks = list(marks)
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                "mark for student {} does not belong to {}".format(
                    mark.student_id, student.student_id
                )
            )

    days = rosterkit.attendance.days_missed(marks)
    if not days:
        raise ValueError("no absences to report for {}".format(student.student_id))

    date_texts = []
    for day in days:
        date_texts.append(day.isoformat())

    if len(days) == 1:
        unit = "day"
    else:
        unit = "days"

    notice = "Dear parent or guardian of {} {}: your child missed {} {} of class on: {}.".format(
        student.first_name, student.last_name, len(days), unit, ", ".join(date_texts)
    )
    return notice
